  { id: '1', name: 'Salmón Fresco Premium (Filete)', price: 18.50, unit: 'kg', stock: 45.5, category: 'Frescos' },
  { id: '2', name: 'Lubina Salvaje Entera', price: 14.00, unit: 'kg', stock: 12.0, category: 'Enteros' },
  { id: '3', name: 'Gambón Rosado Calibre L2', price: 22.00, unit: 'kg', stock: 30.0, category: 'Mariscos' },
  { id: '4', name: 'Pulpo Cocido Gallego', price: 28.90, unit: 'kg', stock: 8.5, category: 'Cocidos' },
];

