              <p className="text-sm font-semibold truncate text-white">{activeVendor}</p>
            </div>
          </div>

          {/* Selector de Modos de Operación */}
          <h2 className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3">Comandas Activas</h2>
          <div className="space-y-2">
            <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 cursor-pointer hover:bg-emerald-500/20 transition-all">
              <div className="flex justify-between items-center">
                <span className="text-sm font-bold text-emerald-400">Mesa / Mostrador #4</span>
                <span className="text-xs px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300">3 items</span>
              </div>
              <p className="text-xs text-slate-400 mt-1">Total: $45.50 • Hace 4 min</p>
            </div>
          </div>
        </div>

        {/* Footer de Estado de Sistema */}
        <div className="pt-4 border-t border-white/10 flex items-center justify-between text-xs text-slate-400">
          <span className="flex items-center gap-1 text-emerald-400">
            <ShieldCheck size={14} /> RLS Seguro
          </span>
          <span>v2.4-prod</span>
        </div>
      </aside>

      {/* COLUMNA 2: Matriz de Productos y Buscador (50%) */}
      <main className="w-1/2 flex flex-col p-6 bg-gradient-to-br from-[#090D16] to-[#0B132B]">

        {/* Barra de Búsqueda Integrada (Sin barras redundantes) */}
        <div className="relative mb-6">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={22} />
          <input 
            type="text" 
            placeholder="Buscar por nombre, código de barras o categoría (Ej: Salmón)..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-900/80 border border-white/10 rounded-2xl py-4 pl-12 pr-4 text-white placeholder-slate-500 focus:outline-none focus:border-cyan-500 focus:ring-2 focus:ring-cyan-500/20 transition-all text-lg shadow-inner"
          />
