              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Grid de Productos Táctil (Tarjetas Glassmorphism) */}
        <div className="grid grid-cols-2 gap-4 overflow-y-auto pr-2 flex-1">
          {MOCK_PRODUCTS.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase())).map(product => (
            <div 
              key={product.id}
              onClick={() => addToCart(product)}
              className="bg-slate-900/60 hover:bg-slate-800/80 border border-white/10 hover:border-cyan-500/50 p-4 rounded-2xl flex flex-col justify-between cursor-pointer transition-all active:scale-95 shadow-xl group"
