              </div>
              <div className="flex items-end justify-between mt-4">
                <div>
                  <span className="text-2xl font-black text-emerald-400">${product.price.toFixed(2)}</span>
                  <span className="text-xs text-slate-400 ml-1">/ {product.unit}</span>
                </div>
                <div className="w-10 h-10 rounded-xl bg-cyan-500/10 group-hover:bg-cyan-500 text-cyan-400 group-hover:text-slate-950 flex items-center justify-center transition-all font-bold">
                  <Plus size={20} />
