      </main>

      {/* COLUMNA 3: Ticket Actual y Cobro (30%) */}
      <section className="w-[30%] bg-[#0B132B]/90 backdrop-blur-xl border-l border-white/10 flex flex-col justify-between p-6 shadow-2xl">

        {/* Cabecera del Ticket */}
        <div>
          <div className="flex items-center justify-between pb-4 border-b border-white/10">
            <div className="flex items-center gap-2">
              <ShoppingCart className="text-cyan-400" size={20} />
              <h2 className="text-lg font-bold text-white">Ticket de Venta</h2>
            </div>
            <button 
              onClick={() => setCart([])}
              className="text-xs text-rose-400 hover:text-rose-300 px-2 py-1 rounded bg-rose-500/10 border border-rose-500/20"
            >
              Limpiar
            </button>
          </div>

          {/* Lista de Items en el Carrito */}
          <div className="h-[36vh] overflow-y-auto divide-y divide-white/5 my-4 pr-1">
            {cart.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-500 text-center">
                <ShoppingCart size={48} className="mb-2 opacity-30" />
                <p className="text-sm">Seleccione productos de la matriz o escanee código de barras</p>
              </div>
            ) : (
              cart.map(item => (
                <div key={item.id} className="py-3 flex items-center justify-between">
                  <div className="flex-1 pr-2">
                    <p className="text-sm font-semibold text-white line-clamp-1">{item.name}</p>
                    <p className="text-xs text-emerald-400 font-medium">${item.price.toFixed(2)} × {item.quantity} {item.unit}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="flex items-center bg-slate-800 rounded-lg border border-white/10">
                      <button onClick={() => updateQuantity(item.id, -0.5)} className="p-1.5 hover:bg-slate-700 text-slate-300 rounded-l-lg">
                        <Minus size={14} />
                      </button>
                      <span className="px-2 text-xs font-bold text-white">{item.quantity}</span>
                      <button onClick={() => updateQuantity(item.id, 0.5)} className="p-1.5 hover:bg-slate-700 text-slate-300 rounded-r-lg">
                        <Plus size={14} />
                      </button>
                    </div>
                  </div>
                </div>
