              <span className="text-emerald-400">${total.toFixed(2)}</span>
            </div>
          </div>

          {/* Botonera de Cobro Táctil Rápido (Menos de 3 toques) */}
          <div className="grid grid-cols-2 gap-2 pt-2">
            <button 
              disabled={cart.length === 0}
              className="py-4 rounded-xl bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white font-bold flex flex-col items-center justify-center gap-1 border border-white/10 transition-all active:scale-95"
            >
              <Banknote size={20} className="text-cyan-400" />
              <span className="text-xs">Efectivo Exacto</span>
            </button>
            <button 
              disabled={cart.length === 0}
              className="py-4 rounded-xl bg-emerald-500 hover:bg-emerald-400 disabled:opacity-50 text-slate-950 font-black flex flex-col items-center justify-center gap-1 shadow-lg shadow-emerald-500/20 transition-all active:scale-95"
            >
              <CreditCard size={20} />
              <span className="text-xs">Cobrar Tarjeta</span>
            </button>
          </div>

          <button 
            disabled={cart.length === 0}
